func (m *GenerateCodeResponse) validate(all bool) error {
	if m == nil {
		return nil
	}

	var errors []error

	for idx, item := range m.GetFiles() {
		_, _ = idx, item

		if all {
			switch v := interface{}(item).(type) {
			case interface{ ValidateAll() error }:
				if err := v.ValidateAll(); err != nil {
					errors = append(errors, GenerateCodeResponseValidationError{
						field:  fmt.Sprintf("Files[%v]", idx),
						reason: "embedded message failed validation",
						cause:  err,
					})
				}
			case interface{ Validate() error }:
				if err := v.Validate(); err != nil {
					errors = append(errors, GenerateCodeResponseValidationError{
						field:  fmt.Sprintf("Files[%v]", idx),
						reason: "embedded message failed validation",
						cause:  err,
					})
				}
			}
		} else if v, ok := interface{}(item).(interface{ Validate() error }); ok {
			if err := v.Validate(); err != nil {
				return GenerateCodeResponseValidationError{
					field:  fmt.Sprintf("Files[%v]", idx),
					reason: "embedded message failed validation",
					cause:  err,
				}
			}
		}

	}

	// no validation rules for Id

	if len(errors) > 0 {
		return GenerateCodeResponseMultiError(errors)
	}

	return nil
}

// GenerateCodeResponseMultiError is an error wrapping multiple validation
// errors returned by GenerateCodeResponse.ValidateAll() if the designated
// constraints aren't met.
type GenerateCodeResponseMultiError []error

// Error returns a concatenation of all the error messages it wraps.
func (m GenerateCodeResponseMultiError) Error() string {
	msgs := make([]string, 0, len(m))
	for _, err := range m {
		msgs = append(msgs, err.Error())
	}
	return strings.Join(msgs, "; ")
}

// AllErrors returns a list of validation violation errors.
func (m GenerateCodeResponseMultiError) AllErrors() []error { return m }

// GenerateCodeResponseValidationError is the validation error returned by
// GenerateCodeResponse.Validate if the designated constraints aren't met.
type GenerateCodeResponseValidationError struct {
	field  string
	reason string
	cause  error
	key    bool
}

// Field function returns field value.
func (e GenerateCodeResponseValidationError) Field() string { return e.field }

// Reason function returns reason value.
func (e GenerateCodeResponseValidationError) Reason() string { return e.reason }

// Cause function returns cause value.
func (e GenerateCodeResponseValidationError) Cause() error { return e.cause }

// Key function returns key value.
func (e GenerateCodeResponseValidationError) Key() bool { return e.key }

// ErrorName returns error name.
func (e GenerateCodeResponseValidationError) ErrorName() string {
	return "GenerateCodeResponseValidationError"
}

// Error satisfies the builtin error interface
func (e GenerateCodeResponseValidationError) Error() string {
	cause := ""
	if e.cause != nil {
		cause = fmt.Sprintf(" | caused by: %v", e.cause)
	}

	key := ""
	if e.key {
		key = "key for "
	}

	return fmt.Sprintf(
		"invalid %sGenerateCodeResponse.%s: %s%s",
		key,
		e.field,
		e.reason,
		cause)
}

var _ error = GenerateCodeResponseValidationError{}

var _ interface {
	Field() string
	Reason() string
	Key() bool
	Cause() error
	ErrorName() string
} = GenerateCodeResponseValidationError{}
